17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.regex.Pattern;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
28	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
29	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.util.StringUtils;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
64	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
65	     * addresses are lower-cased before being stored.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        validateRequiredFields(ownerFieldsDto);
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
120	        owner.setEmail(normalizeEmail(owner.getEmail()));
121	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
122	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
123	        }
124	        this.clinicService.saveOwner(owner);
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        headers.setLocation(UriComponentsBuilder.newInstance()
127	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
128	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
129	    }
130	
131	    /**
132	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
133	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
134	     * so the client receives a 400 whose {@code errors} array lists each missing field.
135	     *
136	     * @param ownerFieldsDto the submitted owner fields
137	     */
138	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
139	        List<String> missingFields = new ArrayList<>();
140	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
141	            missingFields.add("firstName");
142	        }
143	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
144	            missingFields.add("lastName");
145	        }
146	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
147	            missingFields.add("address");
148	        }
149	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
150	            missingFields.add("city");
151	        }
152	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
153	            missingFields.add("telephone");
154	        }
155	        if (!missingFields.isEmpty()) {
156	            throw new MissingOwnerFieldsException(missingFields);
157	        }
158	    }
159	
160	    /**
161	     * Normalizes a telephone number for owner creation by stripping every non-digit character and
162	     * requiring exactly ten digits to remain. The stripped, ten-digit value is what gets stored and
163	     * returned.
164	     *
165	     * @param telephone the raw telephone value submitted by the client
166	     * @return the normalized ten-digit telephone number
167	     * @throws InvalidOwnerFieldsException if the value does not contain exactly ten digits after stripping
168	     */
169	    private String normalizeTelephone(String telephone) {
170	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
171	        if (digits.length() != 10) {
172	            throw new InvalidOwnerFieldsException(List.of("telephone"));
173	        }
174	        return digits;
175	    }
176	
